//! Passive Text algorithms preserve native identity, records and live ranges.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse_loaded_document_with_scripting("<body><noscript id=host>held</noscript><button id=button><noscript id=guard>guarded</noscript></button><p id=out>Real</p>",true,&||Ok(())).unwrap();let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://noscript-text-algorithms.test/",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
fn refusal(d:&mut Document,f:&mut Forms,p:&mut Page,code:&str)->String{let source=format!("var caughtFailure=null;try{{{code}}}catch(e){{caughtFailure=e.name+': '+e.message;}}");match p.runtime.execute(&source,&mut Bridge{doc:d,forms:f,state:&mut p.state}){Err(e)=>e,Ok(_)=>{let value=p.runtime.execute("caughtFailure",&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();let Value::String(message)=value else{panic!("Expected an actual native refusal: {value:?}")};message}}}
const ADJACENT:&str=r#"var donor=document.implementation.createHTMLDocument('owner'),source=donor.createElement('noscript');source.appendChild(donor.createTextNode('A\udfff'));source.appendChild(donor.createTextNode('\ud800B'));source.appendChild(donor.createTextNode(''));var host=document.importNode(source,true);host.id='adjacent';document.body.appendChild(host);var text=host.firstChild,second=text.nextSibling,empty=host.lastChild;"#;
#[test]
fn noscript_text_algorithms_split_exact_units_actual_records_identity_and_live_range(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var host=document.getElementById('host'),text=host.firstChild,raw='A\udfff\ud800B';text.data=raw;var range=document.createRange(),watch=new MutationObserver(function(){});range.setStart(text,3);range.setEnd(text,4);watch.observe(host,{childList:true,characterData:true,characterDataOldValue:true,subtree:true});var tail=text.splitText(2),rs=watch.takeRecords();if(host.firstChild!==text||host.lastChild!==tail||text.nextSibling!==tail||tail.previousSibling!==text||tail.ownerDocument!==document||tail.parentNode!==host||text.data!=='A\udfff'||tail.data!=='\ud800B'||text.wholeText!==raw||tail.wholeText!==raw||host.innerHTML!==raw||range.startContainer!==tail||range.startOffset!==1||range.endContainer!==tail||range.endOffset!==2||rs.length!==2||rs[0].type!=='childList'||rs[0].target!==host||rs[0].addedNodes[0]!==tail||rs[0].previousSibling!==text||rs[0].nextSibling!==null||rs[1].type!=='characterData'||rs[1].target!==text||rs[1].oldValue!==raw)throw 'actual passive UTF16 split';var boundary=tail.splitText(tail.length);rs=watch.takeRecords();if(boundary.data!==''||boundary.parentNode!==host||tail.nextSibling!==boundary||host.childNodes.length!==3||rs.length!==2||rs[0].addedNodes[0]!==boundary||rs[1].oldValue!=='\ud800B'||range.endContainer!==tail||range.endOffset!==2)throw 'end split preserves actual empty Text';"#);assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_dynamic_stylesheets().is_empty());
}
#[test]
fn noscript_text_algorithms_normalize_actual_imported_adjacent_text_records_and_ranges(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,ADJACENT);run(&mut d,&mut f,&mut p,r#"var range=document.createRange(),watch=new MutationObserver(function(){});range.setStart(second,0);range.setEnd(second,2);watch.observe(host,{childList:true,characterData:true,characterDataOldValue:true,subtree:true});host.normalize();var rs=watch.takeRecords(),raw='A\udfff\ud800B';if(host.childNodes.length!==1||host.firstChild!==text||text.data!==raw||host.innerHTML!==raw||second.parentNode!==null||second.data!=='\ud800B'||empty.parentNode!==null||empty.data!==''||text.ownerDocument!==document||second.ownerDocument!==document||range.startContainer!==text||range.startOffset!==2||range.endContainer!==text||range.endOffset!==4||rs.length!==3||rs[0].type!=='characterData'||rs[0].target!==text||rs[0].oldValue!=='A\udfff'||rs[1].type!=='childList'||rs[1].removedNodes[0]!==second||rs[1].previousSibling!==text||rs[1].nextSibling!==empty||rs[2].removedNodes[0]!==empty||rs[2].previousSibling!==text||rs[2].nextSibling!==null)throw 'actual passive normalization';host.normalize();rs=watch.takeRecords();if(rs.length!==1||rs[0].type!=='characterData'||rs[0].oldValue!==raw||rs[0].target!==text||host.firstChild!==text)throw 'singleton normalization record';"#);assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_dynamic_stylesheets().is_empty());
}
#[test]
fn noscript_text_algorithms_native_ancestor_guards_refuse_without_range_or_record_prefix(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var guarded=document.getElementById('guard'),text=guarded.firstChild,range=document.createRange(),watch=new MutationObserver(function(){});range.setStart(text,1);range.setEnd(text,3);watch.observe(document.body,{childList:true,characterData:true,subtree:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;let values=f.controls.values().map(|c|c.value.text()).collect::<Vec<_>>();for code in ["text.splitText(2);","guarded.normalize();"]{p.begin_job();let e=refusal(&mut d,&mut f,&mut p,code);assert!(e.contains("inert resource subtrees"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);assert_eq!(f.controls.values().map(|c|c.value.text()).collect::<Vec<_>>(),values);p.begin_job();run(&mut d,&mut f,&mut p,"if(guarded.firstChild!==text||text.data!=='guarded'||range.startContainer!==text||range.endContainer!==text||range.startOffset!==1||range.endOffset!==3||watch.takeRecords().length)throw 'protected Text algorithms unchanged';");}p.begin_job();run(&mut d,&mut f,&mut p,"document.getElementById('out').textContent='Recovered';");assert!(p.take_dynamic_scripts().is_empty());
}
#[test]
fn noscript_text_algorithms_copy_work_retained_refusals_are_atomic_and_recover(){
 for normalize in [false,true]{let(mut d,mut f,mut p)=fixture();if normalize{run(&mut d,&mut f,&mut p,ADJACENT);run(&mut d,&mut f,&mut p,&format!("var quotaTail='{}';second.data=quotaTail;","R".repeat(4096)));}else{run(&mut d,&mut f,&mut p,"var host=document.getElementById('host'),text=host.firstChild;");}run(&mut d,&mut f,&mut p,"var original=text.data,range=document.createRange(),watch=new MutationObserver(function(){});range.setStart(text,0);range.setEnd(text,1);watch.observe(host,{childList:true,characterData:true,characterDataOldValue:true,subtree:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;let limit=p.state.retained_limit;let code=if normalize{"host.normalize();"}else{"text.splitText(2);"};for mode in 0..3{p.begin_job();match mode{0=>p.state.copy_work=0,1=>p.state.host_work=0,_=>p.state.retained_limit=p.state.retained};let e=refusal(&mut d,&mut f,&mut p,code).to_ascii_lowercase();assert!(match mode{0=>e.contains("dom string work limit"),1=>e.contains("dom work limit"),_=>e.contains("allowance")||e.contains("retained")||e.contains("storage")},"normalize={normalize} mode={mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.state.retained_limit=limit;p.begin_job();run(&mut d,&mut f,&mut p,"if(host.firstChild!==text||text.data!==original||range.startContainer!==text||range.endContainer!==text||range.startOffset!==0||range.endOffset!==1||watch.takeRecords().length)throw 'Text algorithm refusal atomic';");}p.begin_job();run(&mut d,&mut f,&mut p,code);run(&mut d,&mut f,&mut p,if normalize{r#"var rs=watch.takeRecords();if(host.firstChild!==text||host.childNodes.length!==1||text.data!=='A\udfff'+quotaTail||rs.length!==3||rs[0].oldValue!==original||second.parentNode!==null||empty.parentNode!==null)throw 'fresh normalization recovery';"#}else{"var rs=watch.takeRecords();if(host.firstChild!==text||text.data!=='he'||host.lastChild.data!=='ld'||rs.length!==2||rs[0].addedNodes[0]!==host.lastChild||rs[1].oldValue!=='held')throw 'fresh split recovery';"});assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_dynamic_stylesheets().is_empty());}
}
